  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Presuňte celú uloženú konverzáciu, kontrolný zoznam, prílohy a súbory. Relácie poskytovateľov a prihlasovacie údaje zostanú tu. Vlákno v cieľovom umiestnení použije predvolený harness daného počítača a nebude mať väčší prístup než toto vlákno. Nič sa nespustí, kým tam neodošlete ďalšiu správu. Model môžete zmeniť po otvorení vlákna. Toto vlákno zostane tu iba na čítanie na účely obnovy.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Skopírujte súbory a lokálnu históriu Git. Zdrojový projekt a četovanie zostanú tu. V cieľovom umiestnení sa vytvorí nový priečinok. Worktrees použijú nakonfigurovaný adresár worktree.',
