  'At this level: {value0}': 'Na tejto úrovni: {value0}',
  'Project overrides Computer; Project on computer wins over both. The check marks the effective value for each computer, including later overrides.':
    'Projekt má prednosť pred Počítačom; Projekt v počítači má prednosť pred oboma. Začiarknutie označuje výslednú hodnotu pre každý počítač vrátane neskorších prepísaní.',
  'The value above comes from the latest settings read. Source details below use saved snapshots.':
    'Hodnota vyššie pochádza z najnovšie načítaných nastavení. Podrobnosti o zdroji nižšie vychádzajú z uložených snímok.',
