  ' · current draft': ' · aktuálny koncept',
  'These levels keep their own value when {value0} changes. Open one to edit it, or reset them all to inherit again.':
    'Tieto úrovne si zachovajú vlastnú hodnotu aj po zmene {value0}. Otvorte úroveň, ak ju chcete upraviť, alebo všetky obnovte na zdedené hodnoty.',
  'Open {value0} settings for {value1}': 'Otvoriť nastavenia {value0} pre {value1}',
  'Resetting…': 'Obnovuje sa…',
  'Reset all later {value0} overrides': 'Obnoviť všetky neskoršie prepísania {value0}',
  'Use inherited {value0}{value1}': 'Použiť zdedenú hodnotu {value0}{value1}',
  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Nastavte CuaDriver na hostiteľskom počítači runtime prostredia. CuaDriver spravuje oprávnenia operačného systému; Dovo pripája agentov cez MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Názvy alebo cesty k spustiteľným súborom hostiteľa bez úvodzoviek shellu. Prepísania agenta majú prednosť. Nové terminály používajú tieto nastavenia shellu.',
  'Loading {value0} settings…': 'Načítavajú sa nastavenia {value0}…',
  'computer-use': 'computer-use',
  command: 'command',
  'Shell arguments (one per line)': 'Argumenty shellu (jeden na riadok)',
  'Automatic shell: {value0}. Default: -l (login shell).':
    'Automatický shell: {value0}. Predvolená hodnota: -l (prihlasovací shell).',
  'Enable agent computer use on this computer':
    'Povoliť agentovi používať počítač na tomto počítači',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Udeľuje agentom s prístupom na zápis prístup k ploche tohto počítača. Agenti s prístupom len na čítanie sú vylúčení. Používateľ a agenti zdieľajú plochu a stav aplikácií.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Ak chcete, aby sa Cua Driver automaticky našiel v premennej PATH alebo v štandardnom inštalačnom priečinku tohto počítača, nechajte pole prázdne. Zmeny sa použijú pri nových ťahoch agenta.',
  '1. Install on this computer': '1. Inštalácia na tomto počítači',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Spustite oficiálny inštalátor na hostiteľskom počítači runtime prostredia a potom obnovte stav. Stiahne a nainštaluje CuaDriver; účet Cua nie je potrebný.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimálne systémy Linux potrebujú libxi6 a at-spi2-core. GNOME potrebuje pribaleného pomocníka WinRects pre Cua; pozrite si sprievodcu inštaláciou.',
  'Install and set up Cua Driver': 'Nainštalovať a nastaviť Cua Driver',
  'Detect / check Cua Driver': 'Zistiť / skontrolovať Cua Driver',
  '2. Permissions & desktop access': '2. Oprávnenia a prístup k ploche',
  '3. Agent MCP, skills & hooks': '3. MCP agenta, zručnosti a háčiky',
  '4. Computer History (optional preview)': '4. História počítača (voliteľná ukážka)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Udeľte CuaDriver prístupnosť a nahrávanie obrazovky v macOS a povoľte jeho reštart. Test prístupu k ploche zobrazí zoznam aplikácií bez ich zmeny. Ovládanie démona ovplyvňuje aktívne relácie používania počítača.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Uložte prepínač používania počítača, aby sa dovo_cua MCP automaticky použil pri nových ťahoch s prístupom na zápis. Ručná registrácia MCP nie je potrebná. Nainštalujte voliteľný oficiálny balík zručností; inštalácia prepojí zistených agentov v tomto počítači.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Voliteľná, šifrovaná história obsahujúca iba metadáta. Zapnutie môže reštartovať démona. Vypnutie zachová zaznamenané údaje; pozastavenie dočasne zastaví nahrávanie. Nepodporované zostavy nahlásia chybu. Údaje zostávajú na hostiteľskom počítači runtime prostredia; možnosť Zobraziť nedávnu históriu tu načíta až 20 udalostí.',
  'Delete recorded Computer History?': 'Odstrániť zaznamenanú Históriu počítača?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Odstránia sa všetky zaznamenané údaje histórie a ich šifrovací kľúč v tomto počítači. Túto akciu nemožno vrátiť späť.',
