  'Prompt suggestions': 'Návrhy výziev',
  'Tab completion': 'Dokončovanie tabulátorom',
  'Suggest a next prompt after a Claude or Codex turn. Tap the suggestion to insert it without sending. On desktop, press Tab to insert it or Escape to dismiss it. Each suggestion makes an extra model request and uses plan usage.':
    'Po ťahu v Claude alebo Codex navrhnúť ďalšiu výzvu. Klepnutím na návrh ho vložíte bez odoslania. Na počítači ho vložíte stlačením klávesu Tab alebo zrušíte klávesom Escape. Každý návrh vyžaduje ďalšiu požiadavku na model a spotrebúva plánované využitie.',
  'Scheduled worker capacity': 'Kapacita plánovaných pracovníkov',
  'Scheduled jobs wait at this threshold. One slot stays available for conversation work. Direct messages and needed children can exceed it. Running work is kept.':
    'Naplánované úlohy čakajú, kým sa dosiahne táto hranica. Jeden slot zostáva voľný na konverzáciu. Priame správy a potrebné podúlohy môžu túto hranicu prekročiť. Prebiehajúca práca sa zachová.',
  'Continue interrupted turns after runtime restart':
    'Pokračovať v prerušených ťahoch po reštarte runtime',
  'Interrupted turns can resume automatically. Queued messages stay paused until you resume them. Stopped tasks and automations still require Retry.':
    'Prerušené ťahy možno automaticky obnoviť. Správy vo fronte zostanú pozastavené, kým ich neobnovíte. Zastavené úlohy a automatizácie je stále potrebné opakovať.',
  'Auto-archive inactive tasks': 'Automaticky archivovať neaktívne úlohy',
  Never: 'Nikdy',
