  'After 14 days': 'Po 14 dňoch',
  'After 30 days': 'Po 30 dňoch',
  'Computer fallback when no scoped archiving rule is set. Scoped On archives after time in Settled; scoped Off disables automatic archiving. Running, waiting, pinned tasks and open terminals are protected.':
    'Predvolená možnosť počítača, keď nie je nastavené pravidlo archivácie v rozsahu. Nastavenie Zapnuté v rozsahu archivuje po uplynutí času v stave Vyriešené; nastavenie Vypnuté vypne automatickú archiváciu. Prebiehajúce, čakajúce a pripnuté úlohy a otvorené terminály sú chránené.',
  'Keep this computer awake while tasks run':
    'Udržiavať tento počítač prebudený počas vykonávania úloh',
  'macOS only. Prevents idle sleep while a task is working, so it keeps going while you follow it here.':
    'Len macOS. Zabraňuje uspatiu pri nečinnosti počas práce úlohy, aby pokračovala, kým ju tu sledujete.',
  'Model modes (experimental)': 'Režimy modelu (experimentálne)',
  'Tune & Maestro modes (experimental)': 'Režimy Tune a Maestro (experimentálne)',
