    'Tune vyberie model v rámci predvoleného agenta. Maestro vyberie agenta aj model. Oba režimy vyberú uvažovanie raz pred prvým ťahom. Dedenie zachová predvolené nastavenia projektu.',
  'Project mode (experimental)': 'Režim projektu (experimentálny)',
  'Scope mode (experimental)': 'Režim Scope (experimentálny)',
  'Scope model mode': 'Režim modelu Scope',
  'Find primary and linked projects from the first message on this computer. If no project matches, continue without a project.':
    'Nájdite hlavné a prepojené projekty podľa prvej správy v tomto počítači. Ak sa nenašiel žiadny zodpovedajúci projekt, pokračujte bez projektu.',
  'Supervised mode': 'Režim pod dohľadom',
  'Always allow web requests on this computer': 'Vždy povoliť webové požiadavky v tomto počítači',
  'Allows browsing and search in every project and thread on this computer. Shell commands and file changes keep their existing approvals.':
    'Umožňuje prehliadanie a vyhľadávanie vo všetkých projektoch a vláknach v tomto počítači. Schvaľovanie príkazov shellu a zmien súborov zostáva nezmenené.',
