  'Use automatic relay': 'Použiť automatický sprostredkovateľ',
  'Relay fallback': 'Náhradný sprostredkovateľ',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Počítač musí povoliť sprostredkovateľa v QR kóde na párovanie. Ak párovanie povoľuje iba priame pripojenia, vygenerujte v počítači nový QR kód s povoleným Dovo a spárujte zariadenie znova.',
  'Scan pairing QR code': 'Naskenovať QR kód na párovanie',
  'Point your camera at the QR code shown by Dovo Studio or the server’s pair command.':
    'Namierte fotoaparát na QR kód zobrazený v Dovo Studio alebo príkazom pair na serveri.',
  'Allow camera access to scan a pairing code. You can also enter the address and code manually.':
    'Povoľte prístup k fotoaparátu na naskenovanie párovacieho kódu. Adresu a kód môžete zadať aj manuálne.',
  'Allow camera': 'Povoliť fotoaparát',
  'Open Settings': 'Otvoriť nastavenia',
  'Try another code': 'Skúsiť iný kód',
  'Enter address and code manually': 'Zadať adresu a kód manuálne',
  'Enter the new address and a fresh pairing code from the same computer. Your saved connection stays unchanged until pairing succeeds.':
    'Zadajte novú adresu a čerstvý párovací kód z toho istého počítača. Uložené pripojenie sa nezmení, kým sa párovanie nedokončí.',
  'On your computer, open Dovo and choose {value0} in Settings → Devices & runtime.':
    'V počítači otvorte Dovo a v časti Nastavenia → Zariadenia a behové prostredie vyberte {value0}.',
  'Connect your phone': 'Pripojiť telefón',
  'Scan the QR code in this app to connect over the internet. No VPN or local IP needed. You can also pair using a LAN / VPN address.':
    'Naskenujte QR kód v tejto aplikácii a pripojte sa cez internet. VPN ani lokálna IP adresa nie sú potrebné. Spárovať sa môžete aj pomocou adresy LAN / VPN.',
  'Internet connection': 'Internetové pripojenie',
  'WebRTC + STUN · end-to-end encrypted. No VPN or computer address needed. Keep Dovo open on the computer.':
    'WebRTC + STUN · end-to-end šifrované. VPN ani adresa počítača nie sú potrebné. Nechajte Dovo otvorené v počítači.',
  'Use a LAN / VPN address instead': 'Namiesto toho použiť adresu LAN / VPN',
