  'Partial results · open PRs to load more': 'Čiastočné výsledky · otvorte PR a načítajte ďalšie',
  'View tasks on this device': 'Zobraziť úlohy v tomto zariadení',
  'This computer connection changed. Choose where to create this work again.':
    'Pripojenie k tomuto počítaču sa zmenilo. Vyberte, kde sa má táto práca znova vytvoriť.',
  'Choose another computer': 'Vybrať iný počítač',
  'Choose where this work should run.': 'Vyberte, kde sa má táto práca vykonať.',
  'Shows connection details': 'Zobraziť podrobnosti o pripojení',
  'Reconnects. Touch and hold for details':
    'Znova sa pripojí. Podržte dotykom, aby sa zobrazili podrobnosti',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Telefón už nie je spárovaný so žiadnym z nižšie uvedených počítačov. Bol z nich odstránený alebo sa behové prostredie obnovilo. Spárujte ho znova v časti Zariadenia v Nastaveniach.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Pripojené pomocou aktualizácií HTTP. Živé vysielanie sa znova pripája alebo nie je dostupné. Opätovným pripojením to skúsite znova.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Uložená práca zostáva dostupná. Znova pripojte počítač, aby ste v ňom mohli odosielať správy alebo spúšťať príkazy.',
  '{value0} · {value1} saved actions': '{value0} · {value1} uložených akcií',
  'Thread: {value0}': 'Vlákno: {value0}',
  'Computer access changed. This action may already have run.':
    'Prístup k počítaču sa zmenil. Táto akcia sa už mohla vykonať.',
  'Retry action': 'Skúsiť akciu znova',
