  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Spárovať znova',
  'Connection stages': 'Fázy pripojenia',
  'Start your computer': 'Spustiť počítač',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Otvorte Dovo v počítači a nechajte ho zapnutý. V Nastaveniach → Zariadenia a behové prostredie sa prihláste a povoľte Dovo Connect. Prihláste sa do rovnakého účtu v telefóne a vyberte možnosť Pripojiť. Na prístup cez internet nepotrebujete párovací kód, VPN ani lokálnu IP adresu.',
  'Direct internet connection': 'Priame internetové pripojenie',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN pripája telefón priamo k počítaču. Váš obsah je šifrovaný end-to-end. Povolením Dovo Connect sa povoľuje šifrované náhradné pripojenie cez sprostredkovateľa, ak sieť blokuje priame pripojenia. Sprostredkovateľ prenáša šifrovanú komunikáciu a nemôže čítať váš obsah.',
  'LAN / VPN connections': 'Pripojenia LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Spárujte LAN / VPN samostatne, aby sa toto pripojenie uprednostnilo, keď je dostupné. Skopírujte celú adresu Wi-Fi, Tailscale, NetBird alebo HTTPS zobrazenú v počítači vrátane portu. localhost a 0.0.0.0 nie sú adresy, ku ktorým sa telefón môže pripojiť.',
  'Check your network': 'Skontrolovať sieť',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Použite rovnakú sieť Wi-Fi alebo pripojte obe zariadenia k svojej VPN. Pri pripojení cez Wi-Fi povoľte Dovo prístup k lokálnej sieti v Nastaveniach iPhonu.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Platnosť párovacích kódov vyprší po dvoch minútach. Kódy z CLI sa schvália automaticky; kód z počítačovej aplikácie môže vyžadovať schválenie v počítači.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Párovanie je uložené. Pred vytvorením ďalšieho kódu skúste Znova pripojiť. Ak sa adresa zmenila, v nastaveniach tohto počítača vyberte Aktualizovať adresu pripojenia.',
