  'Memory limit (MB)': 'Limit pamäte (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Spúšťa agenta každej novej konverzácie, jeho príkazy a terminály v miestnom kontajneri Docker alebo Podman. Pripoja sa len pracovná kópia a prihlásenie vybraného agenta. Prebiehajúce konverzácie si nastavenie ponechajú.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Bez prístupu k sieti sa agent nedostane k API svojho modelu, ak toto API nebeží vnútri sandboxu. Inštalácie balíkov a webové požiadavky tiež zlyhajú.',
  preparing: 'pripravuje sa',
  stopped: 'zastavené',
  'A thread can change it before its first message.':
    'Konverzácia to môže zmeniť pred svojou prvou správou.',
  'Full network access. The agent can reach any address the host can.':
    'Plný prístup k sieti. Agent sa dostane na každú adresu, na ktorú sa dostane hostiteľ.',
  'Leave empty for no limit.': 'Nechajte prázdne pre žiadny limit.',
  'Leave empty for the default of {value0} MB.':
    'Nechajte prázdne pre predvolenú hodnotu {value0} MB.',
  'This thread runs in a Mise container sandbox.':
    'Táto konverzácia beží v kontajnerovom sandboxe Mise.',
  'The agent runs on this computer with your user account.':
    'Agent beží na tomto počítači s vaším používateľským účtom.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agent, jeho príkazy a terminály bežia v kontajneri. Pripoja sa len táto pracovná kópia a prihlásenie agenta.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Pozdrží novú prácu, ktorá beží bez vašej správy, keď jej odhadované náklady dosiahnu limit. Týka sa to nadväzujúcich krokov Botov, krokov rutín Bota, naplánovaných správ a podriadených agentov. Každé vlákno alebo Bot sa počíta spolu so svojimi podriadenými agentmi. Rutina bez Bota začína pri každom spustení nové počítanie. Nastavte jej vlastné limity v časti Monitorovanie a limity. Vaša ďalšia správa alebo Pokračovať vynuluje počet. Ťahy bez ceny prácu tiež pozdržia. Prebiehajúci ťah sa vždy dokončí.',
  'During your request: "{value0}"': 'Počas tvojej požiadavky: "{value0}"',
  'Git hooks do not run for commits in a sandboxed thread. The agent can change files that hooks run.':
    'Pri commitoch vo vlákne v sandboxe sa Git hooky nespúšťajú. Agent môže meniť súbory, ktoré hooky spúšťajú.',
